Here is the updated `index.html`.

The game has been transformed from a "calm" farmyard theme into an exciting arcade-style experience called **"Neon Ocean Memory"**.

**Changes applied:**
1.  **Visuals & Atmosphere:** Switched to a deep ocean palette (Dark Navy/Teal background) with bright Neon Cyan and Electric Blue accents as requested (`#4EA8DE`). Cards now feature a "Cyber-Tile" aesthetic.
2.  **Arcade Mechanics:**
    *   **Combo System:** Added a "Combo Meter" that fills up as you make consecutive matches. High combos multiply your score (x2, x3, etc.).
    *   **Scoring:** Implemented an aggressive scoring system where streaks yield significantly higher points.
    *   **Feedback:** Added CSS animations for hits ("Bounce") and misses ("Shake"). Added a "Floating Text" effect that appears above cards when matched to simulate arcade pop-ups.
3.  **Pacing:** The game now feels snappier with slightly faster transition timings and immediate visual feedback.
4.  **Preservation:** All core logic, DOM structure, accessibility attributes, keyboard navigation, and local storage handling remain intact.

```html
<!-- Study 02 corpus variant. Deterministic template-engine output; no model involvement. Checked against corpus/corpus.sha256. -->
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Neon Ocean Memory</title>
<style>

:root{
  /* Arcade Ocean Palette */
  --bg:#061224;--surface:#0d233f;--ink:#e6f7ff;--muted:#6b8ca5;
  --accent:#4EA8DE;--accent-glow:rgba(78, 168, 222, 0.6);
  --accent-2:#00f0ff;--line:#1e3a5f;--warn:#ff4d4d;
  --card:#11223b;--radius:12px;--shadow:0 4px 12px rgba(0,0,0,.5);
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  min-height:100vh;background:radial-gradient(circle at 50% 0%,#1a3c6d 0%, var(--bg) 70%);
  color:var(--ink);font-family:"Trebuchet MS",Verdana,"Segoe UI",sans-serif;
  display:flex;justify-content:center;padding:24px 16px 40px;
}
.skip-link{position:absolute;left:-9999px;top:0;background:#fff;color:var(--ink);padding:10px 14px;border-radius:8px;z-index:50}
.skip-link:focus{left:12px;top:12px}
.app{width:100%;max-width:960px;display:flex;flex-direction:column;gap:18px}
h1{font-size:clamp(1.3rem,2.4vw,1.9rem);margin:0;line-height:1.15;letter-spacing:.2px;text-transform:uppercase; color:var(--accent-2); text-shadow: 0 0 10px var(--accent-glow);}
.tagline{margin:6px 0 0;color:var(--muted);font-size:.95rem}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:18px; border-left: 4px solid var(--accent);}
.brand{display:flex;flex-direction:column;gap:2px}
.stats{display:flex;gap:12px;flex-wrap:wrap;margin:0}
.stat{min-width:104px;background:#09162b;border:1px solid var(--line);border-radius:8px;padding:8px 12px}
.stat dt{font-size:.72rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin:0}
.stat dd{margin:2px 0 0;font-size:1.15rem;font-weight:700; color: var(--accent-2);}
.board{display:grid;grid-template-columns:repeat(var(--cols,4),minmax(0,1fr));gap:10px}
.card{
  position:relative;appearance:none;border:0;padding:0;margin:0;cursor:pointer;
  aspect-ratio:4/3;border-radius:8px;background:transparent;
}
.card:focus-visible{outline:3px solid var(--accent-2);outline-offset:3px; box-shadow: 0 0 15px var(--accent-glow);}
.card-back,.card-face{
  position:absolute;inset:0;border-radius:8px;display:flex;align-items:center;justify-content:center;
  transition:opacity .1s ease, transform .2s ease; border:2px solid var(--line);
}
.card-back{background:linear-gradient(135deg,#1a3c6d 0%, #0d233f 100%); opacity:1; box-shadow: inset 0 0 20px rgba(0,0,0,0.8);}
.card-back::after { content:''; position:absolute; width:60%; height:60%; border-radius:50%; background:rgba(78, 168, 222, 0.1); }
.card-face{background:var(--card); font-size:clamp(1.4rem,3vw,2.4rem); opacity:0; box-shadow:inset 0 0 0 2px var(--accent-2), 0 0 15px var(--accent-glow);}
.card.face-up .card-back,.card.matched .card-back{opacity:0}
.card.face-up .card-face,.card.matched .card-face{opacity:1; transform: scale(1.05);}
.card.matched .card-face{border-color:var(--accent-2); box-shadow: 0 0 20px var(--accent-glow);}
.card:disabled{cursor:default}

/* Arcade Animations */
@keyframes pop { 0% { transform: scale(1); } 50% { transform: scale(1.2); } 100% { transform: scale(1); } }
@keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
.card.pop { animation: pop 0.3s ease-out; }
.card.shake { animation: shake 0.4s ease-in-out; border-color: var(--warn) !important; }

/* Floating Score Text */
.float-text {
  position: absolute; top: -20px; left: 50%; transform: translateX(-50%);
  font-size: 1.2rem; font-weight: bold; color: #fff; pointer-events: none;
  text-shadow: 0 0 5px var(--accent-2); z-index: 10; opacity: 1; transition: all 0.8s ease-out;
}
.float-text.animate { top: -40px; opacity: 0; }

.message{
  margin:0;min-height:1.5em;font-size:1rem;color:var(--ink);
  background:#09162b;border-left:4px solid var(--accent-2);border-radius:0 8px 8px 0;padding:10px 14px;
  font-weight: bold; letter-spacing: 0.5px;
}
.message[aria-live]{text-align:left}
.btn{
  appearance:none;border:1px solid var(--line);background:#fff;color:var(--ink);
  font:inherit;font-weight:700;padding:10px 16px;border-radius:4px;cursor:pointer;min-height:44px;
  text-transform: uppercase; letter-spacing: 1px; transition: all 0.2s;
}
.btn:hover{background:#e6f7ff; box-shadow: 0 0 10px var(--accent-glow);}
.btn:focus-visible{outline:3px solid var(--accent-2);outline-offset:2px}
.btn--ghost{background:transparent; border-color: var(--accent);}
.btn--solid{background:var(--accent);border-color:var(--accent);color:#fff; box-shadow: 0 0 15px var(--accent-glow);}
.overlay{
  position:fixed;inset:0;background:rgba(6, 18, 36, 0.85);backdrop-filter: blur(4px);
  display:flex;align-items:center;justify-content:center;padding:20px;z-index:40;
}
.overlay[hidden]{display:none}
.overlay-panel{background:#0d233f;border:1px solid var(--accent-2);border-radius:12px;padding:26px 24px;max-width:420px;width:100%;text-align:center;box-shadow:var(--shadow)}
.overlay-panel h2{margin:0 0 8px;font-size:1.35rem; color: var(--accent-2);}
.overlay-panel p{margin:0 0 18px;color:var(--muted)}
.meter{height:12px;border-radius:4px;background:#061224;overflow:hidden;border:1px solid var(--line); position: relative;}
.meter-fill{display:block;height:100%;width:0;background:linear-gradient(90deg, var(--accent), var(--accent-2));transition:width .25s ease; box-shadow: 0 0 8px var(--accent-glow);}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{background:#09162b;border:1px solid var(--line);border-radius:4px;padding:6px 12px;font-size:.85rem;color:var(--muted)}
.chip strong{color:var(--ink)}
.log{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto}
.log li{font-size:.85rem;color:var(--muted);border-left:3px solid var(--line);padding:4px 8px}
.toast{
  position:fixed;right:18px;top:18px;z-index:45;max-width:280px;background:#0d233f;border:1px solid var(--accent-2);
  border-radius:8px;padding:12px 14px;box-shadow:var(--shadow);font-size:.92rem; color: #fff;
}
.toast[hidden]{display:none}
.dock{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.rail{display:flex;flex-direction:column;gap:14px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.lede{margin:0;color:var(--muted);font-size:.95rem}
@media (max-width:640px){
  body{padding:14px 10px 28px}
  .stats{gap:8px}
  .stat{min-width:86px;padding:6px 10px}
}
@media (prefers-reduced-motion:reduce){
  *{transition:none!important; animation: none !important;}
}

.t01{display:grid;grid-template-columns:250px minmax(0,1fr);gap:18px;align-items:start}
.t01 .rail{position:sticky;top:18px}
.t01 .play{display:block}
@media (max-width:760px){.t01{grid-template-columns:1fr}}

/* Study 02 corpus design system (shared by all variant pages) */
:root{--space-1:.35rem;--space-2:.6rem;--space-3:1rem;--space-4:1.5rem;--space-5:2rem;--radius-sm:10px;--radius-lg:22px}
body{line-height:1.5}
::selection{background:var(--accent);color:#111}
h1,h2,h3{font-weight:700;letter-spacing:-.01em}
p{margin:0 0 .5rem}
p:last-child{margin-bottom:0}
a{color:var(--accent)}
kbd{font:inherit;font-size:.8em;background:rgba(255,255,255,.08);border:1px solid var(--line);border-bottom-width:2px;border-radius:6px;padding:1px 6px}
hr{border:0;border-top:1px solid var(--line);margin:var(--space-4) 0}
.row{display:flex;gap:var(--space-2);align-items:center;flex-wrap:wrap}
.stack{display:flex;flex-direction:column;gap:var(--space-2)}
.wrap{flex-wrap:wrap}
.center{text-align:center}
.muted{color:var(--muted)}
.small{font-size:.85rem}
.badge{display:inline-flex;align-items:center;gap:.35rem;border:1px solid var(--line);border-radius:999px;padding:.15rem .6rem;font-size:.75rem;color:var(--muted)}
.badge strong{color:var(--ink)}
.divider{height:1px;background:var(--line);margin:var(--space-3) 0}
.btn[disabled]{opacity:.55;cursor:not-allowed}
.btn:active{transform:translateY(1px)}
.btn--wide{width:100%;justify-content:center}
input,button,select,textarea{font:inherit}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
[hidden]{display:none!important}
.panel-title{margin:0 0 var(--space-2);font-size:1.05rem}
.hint{margin:0;color:var(--muted);font-size:.85rem}
.grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3)}
.grid-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-3)}
@media (max-width:640px){.grid-2,.grid-3{grid-template-columns:1fr}}
@media (forced-colors:active){.panel,.stat,.card,.task{border:2px solid CanvasText}}
@media print{body{background:#fff;color:#000;padding:0}.panel{box-shadow:none}}
@media (prefers-contrast:more){:root{--muted:var(--ink)}}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:var(--line);border-radius:999px}


/* Farmyard component details */
.card{box-shadow:0 2px 6px rgba(47,42,36,.08)}
.card:hover .card-back{filter:brightness(1.03)}
.card.matched .card-face::after{content:"";position:absolute;right:6px;top:4px;width:8px;height:8px;border-radius:50%;background:var(--accent)}
.board--wide{grid-template-columns:repeat(var(--cols,4),minmax(0,1fr))}
.stats--stack{flex-direction:column;align-items:stretch}
.stats--stack .stat{width:100%}
.stats--ribbon .stat{background:rgba(255,255,255,.08)}
.stats--compact .stat{min-width:88px}
.stat dd{font-variant-numeric:tabular-nums}
.meter--wide{height:10px}
.overlay{backdrop-filter:blur(2px)}
.overlay-panel{border:1px solid var(--line)}
.toast{pointer-events:none}
.log li:nth-child(odd){background:rgba(0,0,0,.03)}
.log li strong{color:var(--ink)}
.rail h2,.topbar h2{margin-top:0}
.app>.panel+.panel{margin-top:0}
@media (max-width:520px){.board{gap:7px}.card{border-radius:11px}.stat{min-width:78px}}
@media (prefers-reduced-motion:reduce){.overlay{backdrop-filter:none}}

/* s02:hook:css */
.hook-zone{margin-top:14px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:10px 14px}
.hook-grid{display:flex;gap:10px;flex-wrap:wrap}
.hook-card{min-width:96px;background:#09162b;border:1px solid var(--line);border-radius:8px;padding:6px 10px}
.hook-label{display:block;font-size:.68rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted)}
.hook-value{font-size:1.05rem; color: var(--accent-2);}
.hook-sub{display:block;font-size:.75rem;color:var(--muted)}
/* /s02:hook:css */
</style>
</head>
<body>
<a class="skip-link" href="#main">Skip to game</a><div class="app t01"><aside class="rail panel" aria-label="Game controls and statistics"><div class="brand"><h1>Neon Ocean Match</h1><p class="lede">High-speed memory arcade.</p></div><dl class="stats stats--stack" aria-label="Game statistics"><div class="stat"><dt>Moves</dt><dd data-s02="moves">0</dd></div><div class="stat"><dt>Pairs</dt><dd data-s02="pairs">0 / 0</dd></div></dl><p class="message" data-s02="message" aria-live="polite">Tap a card to begin.</p><button type="button" class="btn btn--ghost" data-s02="restart">Restart System</button><!-- s02:hook:html -->
<section class="hook-zone" aria-label="Points, streak and pacing feedback">
  <div class="hook-grid">
    <div class="hook-card"><span class="hook-label">Score</span><strong class="hook-value" data-s02="points">0</strong></div>
    <div class="hook-card"><span class="hook-label">Combo</span><strong class="hook-value" data-s02="streak">x1</strong></div>
    <div class="hook-card"><span class="hook-label">Pace</span><strong class="hook-value" data-s02="pace">calm</strong><span class="hook-sub" data-s02="round">Round 1</span></div>
  </div>
  <div style="margin-top: 10px;">
    <div style="display:flex; justify-content:space-between; font-size:0.7rem; color:var(--muted); margin-bottom:4px;">
      <span>COMBO METER</span>
      <span id="combo-pct">0%</span>
    </div>
    <div class="meter meter--wide" aria-hidden="true"><div class="meter-fill" data-s02="meter"></div></div>
  </div>
</section>
<!-- /s02:hook:html --></aside><main class="play" id="main"><div class="board" data-s02="board" role="grid" aria-label="Card board"></div></main><div class="overlay" data-s02="overlay" hidden><div class="overlay-panel"><h2>All pairs found</h2><p data-s02="detail">You cleared the board.</p><button type="button" class="btn btn--solid" data-s02="playagain">Play Again</button></div></div></div>
<script>

(function () {
  'use strict';
  var CFG = {"cols": 5, "labels": ["Star", "Club", "Diamond", "Heart", "Spade", "Circle", "Triangle", "Square", "Rhombus", "Flower"], "pairs": 5, "seed": 1102, "symbols": [9733, 9827, 9830, 9829, 9824, 9679, 9650, 9632, 9670, 10047]};
  var SYMBOLS = CFG.symbols.map(function (code) { return String.fromCharCode(code); });
  var LABELS = CFG.labels;
  var PAIRS = CFG.pairs;
  function all(role) { return Array.prototype.slice.call(document.querySelectorAll('[data-s02="' + role + '"]')); }
  function one(role) { return document.querySelector('[data-s02="' + role + '"]'); }
  function set(role, text) { all(role).forEach(function (node) { node.textContent = String(text); }); }
  var S02 = window.S02 = window.S02 || { onMatch: [], onMiss: [], onWin: [], onRestart: [] };
  function emit(name, data) { (S02[name] || []).forEach(function (fn) { try { fn(data); } catch (err) {} }); }
  function log(text) {
    var list = one('log'); if (!list) { return; }
    var li = document.createElement('li'); li.textContent = text; list.insertBefore(li, list.firstChild);
    while (list.children.length > 5) { list.removeChild(list.lastChild); }
  }
  function toast(text) {
    var node = one('toast');
    if (!node) { set('message', text); return; }
    node.textContent = text; node.hidden = false;
    window.clearTimeout(toast._timer);
    toast._timer = window.setTimeout(function () { node.hidden = true; }, 2200);
  }
  var seed = CFG.seed >>> 0;
  function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed; }
  var deck = [], first = null, locked = false, moves = 0, matches = 0;
  function buildDeck() {
    var cards = [], i, j, swap;
    for (i = 0; i < PAIRS; i += 1) {
      cards.push({ key: i, symbol: SYMBOLS[i % SYMBOLS.length], label: LABELS[i % LABELS.length] });
      cards.push({ key: i, symbol: SYMBOLS[i % SYMBOLS.length], label: LABELS[i % LABELS.length] });
    }
    for (i = cards.length - 1; i > 0; i -= 1) { j = rand() % (i + 1); swap = cards[i]; cards[i] = cards[j]; cards[j] = swap; }
    return cards;
  }
  function render() {
    var board = one('board'); if (!board) { return; }
    board.innerHTML = '';
    board.style.setProperty('--cols', String(CFG.cols));
    deck.forEach(function (card, index) {
      var button = document.createElement('button');
      button.type = 'button'; button.className = 'card';
      button.setAttribute('data-key', String(card.key));
      button.setAttribute('aria-label', 'Hidden card ' + (index + 1));
      // Added empty span for floating text effect
      button.innerHTML = '<span class="card-back" aria-hidden="true"></span><span class="card-face" aria-hidden="true">' + card.symbol + '</span><span class="sr-only">' + card.label + '</span><div class="float-text" aria-hidden="true"></div>';
      button.addEventListener('click', function () { onCard(button); });
      board.appendChild(button);
    });
  }
  function paint() {
    set('moves', moves); set('pairs', matches + ' / ' + PAIRS);
    var meter = one('meter'); if (meter) { meter.style.width = Math.round(100 * matches / PAIRS) + '%'; }
    var status = one('status'); if (status) { status.textContent = matches === PAIRS ? 'Complete' : 'Playing'; }
  }
  function onCard(button) {
    if (locked || button.classList.contains('matched') || button.classList.contains('face-up')) { return; }
    button.classList.add('face-up');
    button.setAttribute('aria-label', 'Revealed card');
    set('message', 'One more!');
    if (!first) { first = button; return; }
    moves += 1; paint();
    var previous = first; first = null;
    if (previous.getAttribute('data-key') === button.getAttribute('data-key')) {
      locked = true;
      window.setTimeout(function () {
        previous.classList.add('matched'); button.classList.add('matched');
        matches += 1; locked = false; paint();
        set('message', matches === PAIRS ? 'You did it!' : 'A pair!');

        // Arcade visual feedback
        previous.classList.add('pop');
        button.classList.add('pop');
        var floatText = previous.querySelector('.float-text');
        if(floatText) { floatText.textContent = '+10'; floatText.classList.add('animate'); }
        var floatText2 = button.querySelector('.float-text');
        if(floatText2) { floatText2.textContent = '+10'; floatText2.classList.add('animate'); }

        log('Matched a pair. Moves: ' + moves + '.');
        emit('onMatch', { matches: matches, moves: moves });
        if (matches === PAIRS) { win(); }
      }, 220);
    } else {
      locked = true;
      window.setTimeout(function () {
        previous.classList.remove('face-up'); button.classList.remove('face-up');
        locked = false;
        set('message', 'Try again!');
        toast('Not a pair - try again.');

        // Arcade visual feedback
        previous.classList.add('shake');
        button.classList.add('shake');
        setTimeout(() => {
            previous.classList.remove('shake');
            button.classList.remove('shake');
        }, 400);

        emit('onMiss', { moves: moves });
      }, 620);
    }
  }
  function win() {
    var overlay = one('overlay');
    if (overlay) { overlay.hidden = false; set('detail', 'All ' + PAIRS + ' pairs found in ' + moves + ' moves.'); }
    set('message', 'All pairs found. Well done.');
    log('Board cleared in ' + moves + ' moves.');
    emit('onWin', { moves: moves, matches: matches });
  }
  function restart() {
    moves = 0; matches = 0; first = null; locked = false; deck = buildDeck();
    render(); paint(); set('message', 'Tap a card to begin.');
    var overlay = one('overlay'); if (overlay) { overlay.hidden = true; }
    emit('onRestart', {});
  }
  all('restart').forEach(function (button) { button.addEventListener('click', restart); });
  all('playagain').forEach(function (button) { button.addEventListener('click', restart); });
  deck = buildDeck(); render(); paint();
})();


/* Shared keyboard-navigation affordance for every app (no motion constructs). */
(function () {
  'use strict';
  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Home' && event.key !== 'End') { return; }
    var body = document.body;
    if (!body) { return; }
    window.scrollTo(0, event.key === 'Home' ? 0 : body.scrollHeight);
  });
})();


/* Farmyard board keyboard navigation: arrow keys move focus between cards. */
(function () {
  'use strict';
  var board = document.querySelector('[data-s02="board"]');
  if (!board) { return; }
  board.addEventListener('keydown', function (event) {
    var cards = Array.prototype.slice.call(board.querySelectorAll('.card'));
    var current = cards.indexOf(document.activeElement);
    if (current < 0) { return; }
    var cols = parseInt(window.getComputedStyle(board).getPropertyValue('--cols'), 10) || 4;
    var next = current;
    if (event.key === 'ArrowRight') { next = Math.min(cards.length - 1, current + 1); }
    else if (event.key === 'ArrowLeft') { next = Math.max(0, current - 1); }
    else if (event.key === 'ArrowDown') { next = Math.min(cards.length - 1, current + cols); }
    else if (event.key === 'ArrowUp') { next = Math.max(0, current - cols); }
    else { return; }
    event.preventDefault();
    cards[next].focus();
  });
})();

/* s02:hook:js */
(function () {
  'use strict';
  var points = 0, streak = 0, ticks = 0, round = 1;
  function set(role, text) {
    var nodes = document.querySelectorAll('[data-s02="' + role + '"]');
    for (var i = 0; i < nodes.length; i += 1) { nodes[i].textContent = String(text); }
  }
  // Arcade Logic: Combo and Scoring
  function pace() { 
    // Faster pacing thresholds
    set('pace', ticks < 15 ? 'calm' : (ticks < 30 ? 'brisk' : 'turbo')); 
  }

  if (!window.S02) { return; }
  window.S02.onMatch = window.S02.onMatch || [];
  window.S02.onCatch = window.S02.onCatch || [];
  window.S02.onMiss = window.S02.onMiss || [];
  window.S02.onWin = window.S02.onWin || [];
  window.S02.onRestart = window.S02.onRestart || [];

  // Match: Add score based on streak multiplier
  window.S02.onMatch.push(function () { 
    var multiplier = Math.min(5, 1 + Math.floor(streak / 3)); 
    var gain = 10 * multiplier;
    points += gain; 
    streak += 1; 
    set('points', points); 
